def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    import os
    from itertools import islice

    if not cmd:
        raise ValueError("Command tuple cannot be empty")
    if target_concurrency < 1:
        raise ValueError("Target concurrency must be at least 1")

    def chunks(it, size):
        it = iter(it)
        return iter(lambda: tuple(islice(it, size)), ())

    def run_chunk(chunk):
        full_cmd = cmd + tuple(chunk)
        try:
            if color and os.name == 'posix':
                process = subprocess.Popen(full_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=False, bufsize=1, close_fds=True)
            else:
                process = subprocess.Popen(full_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=False, bufsize=1)
            stdout, stderr = process.communicate()
            return process.returncode, stdout + stderr
        except Exception as e:
            return 1, str(e).encode()

    max_chunk_size = _max_length - sum(len(c) + 1 for c in cmd) - 256  # Reserve some space for environment and other overhead
    results = []

    try:
        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
            for chunk in chunks(varargs, max_chunk_size):
                results.append(executor.submit(run_chunk, chunk))

        all_stdout = b''
        final_returncode = 0
        for future in results:
            returncode, output = future.result()
            all_stdout += output
            if returncode != 0:
                final_returncode = returncode

        return final_returncode, all_stdout

    except Exception as e:
        return 1, str(e).encode()

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    from multiprocessing import Pool
    import os

    if not cmd:
        raise ValueError("Command tuple cannot be empty.")
    if not varargs:
        return 0, b''

    def run_command(args: tuple[str, ...]) -> subprocess.CompletedProcess:
        full_cmd = cmd + args
        try:
            return subprocess.run(full_cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=False)
        except subprocess.CalledProcessError as e:
            return e

    def partition_varargs(varargs: Sequence[str], max_length: int) -> list[tuple[str, ...]]:
        partition = []
        partitions = []
        current_length = len(' '.join(cmd))

        for vararg in varargs:
            if current_length + len(vararg) + 1 > max_length:
                partitions.append(tuple(partition))
                partition = []
                current_length = len(' '.join(cmd))
            partition.append(vararg)
            current_length += len(vararg) + 1
        if partition:
            partitions.append(tuple(partition))
        return partitions

    partitions = partition_varargs(varargs, _max_length)
    with Pool(target_concurrency) as pool:
        results = pool.map(run_command, partitions)

    return_code = 0
    output = b''

    for result in results:
        if isinstance(result, subprocess.CalledProcessError):
            return_code = result.returncode
        output += result.stdout + result.stderr

    return return_code, output

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import os
    import sys
    import subprocess
    from itertools import islice
    from threading import Thread, Lock

    def _get_platform_max_length():
        return os.pathconf('/', 'PC_PATH_MAX')

    if not cmd:
        raise ValueError("Command cannot be empty.")
    if target_concurrency < 1:
        raise ValueError("Target concurrency must be at least 1.")

    results = []
    lock = Lock()

    def worker(args_chunk):
        try:
            full_cmd = cmd + tuple(args_chunk)
            if color and sys.platform.startswith('linux'):
                process = subprocess.run(['stdbuf', '-o', 'L', *full_cmd], capture_output=True, text=True)
            else:
                process = subprocess.run(full_cmd, capture_output=True, text=True)
            with lock:
                results.append((process.returncode, process.stdout.encode('utf-8')))
        except Exception as e:
            with lock:
                results.append((1, str(e).encode('utf-8')))

    threads = []
    try:
        for i in range(0, len(varargs), _max_length):
            args_chunk = varargs[i:i + _max_length]
            thread = Thread(target=worker, args=(args_chunk,))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()
    except Exception as e:
        return (1, str(e).encode('utf-8'))

    combined_output = b''.join(result[1] for result in results)
    return (0 if all(result[0] == 0 for result in results) else 1, combined_output)

