    import os
    import sys

    if not cmd:
        raise ValueError("Command tuple cannot be empty")

    try:
        # Check if the script has a shebang and modify the command accordingly
        script_path = cmd[0]
        if not os.path.isfile(script_path):
            raise FileNotFoundError(f"The script {script_path} does not exist")

        with open(script_path, 'r', encoding='utf-8') as file:
            first_line = file.readline().strip()
            if first_line.startswith('#!'):
                # Shebang found, try to use the interpreter specified in the shebang
                interpreter = first_line[2:].split()[0]
                if os.path.isfile(interpreter) or shutil.which(interpreter):
                    # If the interpreter is directly available, use it
                    cmd = (interpreter,) + cmd
                else:
                    # Otherwise, fallback to using the default python interpreter
                    # with the script path as the first argument
                    cmd = (sys.executable,) + cmd

    except Exception as e:
        # If any error occurs during shebang processing, fall back to using the default interpreter
        cmd = (sys.executable,) + cmd

    return cmd

