def extostr(cls, e, max_level=30, max_path_level=5):
    try:
        if not isinstance(e, Exception):
            raise ValueError("The provided object is not an instance of Exception.")

        if not isinstance(max_level, int) or not isinstance(max_path_level, int):
            raise ValueError("max_level and max_path_level must be integers.")

        if max_level < 0 or max_path_level < 0:
            raise ValueError("max_level and max_path_level must be non-negative integers.")

        exception_type = type(e).__name__
        message = str(e)

        if hasattr(e, '__traceback__'):
            import traceback
            formatted_traceback = traceback.format_exception(type(e), e, e.__traceback__, limit=max_level)
            stack_trace = ''.join(formatted_traceback).split('\n')
            stack_trace = stack_trace[:max_level]

            # Split the traceback into path and line information for path level filtering
            filtered_traceback = []
            for line in stack_trace:
                parts = line.rsplit(':', 1)
                if len(parts) == 2:
                    path, line_info = parts
                    path_parts = path.split('/')
                    if len(path_parts) > max_path_level:
                        path = '/'.join(path_parts[:max_path_level] + ['...'])
                    filtered_traceback.append(f"{path}:{line_info}")
                else:
                    filtered_traceback.append(line)

            stack_trace_str = '\n'.join(filtered_traceback)
            return f"{exception_type}: {message}\n{stack_trace_str}"

        return f"{exception_type}: {message}"

    except Exception as ex:
        return f"Failed to format exception: {str(ex)}"

