def _legacy_mergeOrderings(orderings):
    def merge_two_orderings(order1, order2):
        # Find the first common element
        for i, x in enumerate(order1):
            if x in order2:
                # Split order2 into prefix and suffix at the common element
                split_index = order2.index(x)
                prefix = order2[:split_index]
                suffix = order2[split_index:]
                # Merge order1 up to the common element, then add the suffix
                return order1[:i] + prefix + suffix
        # If no common element is found, just concatenate order1 and order2
        return order1 + order2

    try:
        merged_ordering = []
        for ordering in orderings:
            merged_ordering = merge_two_orderings(merged_ordering, ordering)
        return merged_ordering
    except Exception as e:
        raise ValueError(f"Error merging orderings: {e}")

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    def find_first_occurrence(graph, node):
        for key, value in graph.items():
            if node in value:
                return key
        return None

    try:
        if not orderings:
            return []

        graph = {}
        for ordering in orderings:
            if not ordering:
                continue
            for i in range(len(ordering) - 1):
                current = ordering[i]
                next_node = ordering[i + 1]
                if current not in graph:
                    graph[current] = []
                if next_node not in graph[current]:
                    graph[current].append(next_node)

        merged_order = []
        visited = set()

        def dfs(node):
            if node in visited:
                return
            visited.add(node)
            if node in graph:
                for neighbor in graph[node]:
                    dfs(neighbor)
            merged_order.append(node)

        for ordering in orderings:
            for item in ordering:
                if item not in visited:
                    # Find the root of the current item
                    root = find_first_occurrence(graph, item)
                    if root is not None:
                        dfs(root)
                    else:
                        dfs(item)

        return merged_order[::-1]

    except Exception as e:
        raise ValueError(f"An error occurred during merging orderings: {e}")

