def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Create a set to track unique classes and order them
        unique_classes = []
        seen = set()
        for cls in classes:
            if cls not in seen:
                seen.add(cls)
                unique_classes.append(cls)

        # Use MRO (Method Resolution Order) to determine the minimal set of bases
        mro_bases = set()
        for cls in unique_classes:
            for base in reversed(cls.__mro__):
                if base not in seen:
                    seen.add(base)
                    mro_bases.add(base)

        # Filter out the classes that are already in the unique_classes list
        minimal_bases = [cls for cls in unique_classes if cls not in mro_bases]

        return minimal_bases
    except Exception as e:
        # Handle unexpected errors gracefully
        print(f"An error occurred: {e}")
        return []

