def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    try:
        # Assuming self.SQLParams.in_style is predefined and can be 'named' or 'ordinal'
        if self.SQLParams.in_style == 'named':
            if not isinstance(params, Mapping):
                raise ValueError("Params must be a Mapping for named parameter style.")
            out_params = {f":{key}": value for key, value in params.items()}
            formatted_sql = sql
            for key in params:
                placeholder = f":{key}"
                if placeholder in sql:
                    formatted_sql = formatted_sql.replace(f":{key}", f"${key}")
            return formatted_sql, out_params

        elif self.SQLParams.in_style == 'ordinal':
            if not isinstance(params, Sequence):
                raise ValueError("Params must be a Sequence for ordinal parameter style.")
            out_params = list(params)
            formatted_sql = sql
            for i in range(len(params)):
                placeholder = f"${i + 1}"
                if f"%{i + 1}d" in sql or f"%{i + 1}s" in sql or f"%{i + 1}" in sql:
                    formatted_sql = formatted_sql.replace(f"%{i + 1}d", placeholder)
                    formatted_sql = formatted_sql.replace(f"%{i + 1}s", placeholder)
                    formatted_sql = formatted_sql.replace(f"%{i + 1}", placeholder)
            return formatted_sql, out_params

        else:
            raise ValueError("Unsupported parameter style.")

    except Exception as e:
        raise ValueError(f"An error occurred: {e}")

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    try:
        if isinstance(sql, (str, bytes)):
            if isinstance(params, (dict, collections.abc.Mapping)):
                out_params = {f":{key}": value for key, value in params.items()}
                new_sql = sql
                for key in params:
                    placeholder = '%' + str(key)
                    new_sql = new_sql.replace(placeholder, f":{key}")
                return new_sql, out_params
            elif isinstance(params, (list, tuple, collections.abc.Sequence)):
                out_params = [value for value in params]
                new_sql = sql
                for i in range(len(params)):
                    placeholder = '%' + str(i + 1)
                    new_sql = new_sql.replace(placeholder, f":{i + 1}")
                return new_sql, out_params
            else:
                raise ValueError("Invalid type for params. Must be a dict or a sequence.")
        else:
            raise ValueError("Invalid type for sql. Must be a str or bytes.")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {str(e)}")

