				param_replacer = lambda p: re.sub(r':[a-zA-Z0-9_]+|[1-9]\d*', lambda m: out_style % (p[m.group(0)[1:]] if m.group(0)[0] == ':' else int(m.group(0))), sql)
				converted_params = [p if isinstance(p, dict) else list(p) for p in many_params]
			elif in_style == 'format':
				param_replacer = lambda p: re.sub(r'%\([a-zA-Z_][a-zA-Z0-9_]*\)s', lambda m: out_style % m.group(0)[2:-2], sql)
