            placeholder_pattern = re.compile(r':([a-zA-Z_][a-zA-Z0-9_]*)')
            out_placeholder = '{}' if out_style == 'pyformat' else '?'
            placeholder_replacement = lambda match: out_placeholder
            for params in many_params:
                formatted_sql = placeholder_pattern.sub(placeholder_replacement, formatted_sql)
                out_params.append(list(params.values()))
        elif in_style in ['qmark', 'numeric', 'named', 'format', 'pyformat']:
            placeholder_pattern = re.compile(r'\?|\d+|\%s|\%\(\w+\)\w|%\w')
            placeholder_replacement = lambda match: '{}' if out_style == 'pyformat' else '?'
            formatted_sql = placeholder_pattern.sub(placeholder_replacement, formatted_sql)
            out_params = list(many_params)
        else:
            raise ValueError(f"Unsupported in-style: {in_style}")

        return formatted_sql, out_params

