        in_style = self.SQLParams.in_style
        out_style = self.SQLParams.out_style

        if in_style == 'named':
            param_pattern = re.compile(r':[a-zA-Z0-9_]+')
            out_params = []
            out_sql = sql
            for params in many_params:
                out_param = {}
                for key, value in params.items():
                    new_key = f'p_{len(out_param)}'
                    out_sql = out_sql.replace(f':{key}', f'%({new_key})s')
                    out_param[new_key] = value
                out_params.append(out_param)
        elif in_style in ('qmark', 'numeric', 'named', 'format', 'pyformat'):
            if in_style == 'qmark':
                param_pattern = re.compile(r'\?')
                def replace_func(match):
                    return f'%s'
            elif in_style == 'numeric':
                param_pattern = re.compile(r':\d+')
                def replace_func(match):
                    return f'%({int(match.group()[1:])-1})s'
            elif in_style == 'format':
                param_pattern = re.compile(r'%s')
                def replace_func(match):
                    return f'%s'
            elif in_style == 'pyformat':
                param_pattern = re.compile(r'%\(\w+\)s')
                def replace_func(match):
                    return f'%({match.group()[2:-2]})s'
            out_params = []
            out_sql = param_pattern.sub(replace_func, sql)
            for params in many_params:
                if isinstance(params, dict):
                    out_params.append([params[key.replace(':', '')] for key in param_pattern.findall(sql)])
                else:
                    out_params.append(list(params))
        else:
            raise ValueError(f"Unsupported in-style parameter: {in_style}")

        return out_sql, out_params

    except Exception as e:
