def _extract_number_and_supplment_from_issue_element(issue):
    try:
        issue = issue.lower().strip()
        number = None
        suppl = None

        # Check for number
        if issue.isdigit():
            number = issue
        else:
            # Try to find a pattern with number
            import re
            match = re.match(r'(\d+-?\d*)', issue)
            if match:
                number = match.group(1)

        # Check for supplment
        if 'suppl' in issue or 'spe' in issue:
            suppl = 'suppl'
            if '1' in issue:
                suppl += ' 1'
            elif '2' in issue:
                suppl += ' 2'
            elif '12' in issue:
                suppl += ' 12'
            elif '1-2' in issue:
                suppl += ' 1-2'
            elif 'pr' in issue:
                suppl += ' pr'

        return number, suppl

    except Exception as e:
        return None, None

def _extract_number_and_supplment_from_issue_element(issue):
    try:
        issue = issue.strip().lower()
        number = None
        suppl = None

        # Check for number range
        if '-' in issue:
            parts = issue.split('-', 1)
            number = parts[0].strip()
            remaining = parts[1].strip()
        else:
            number = issue
            remaining = ''

        # Check for supplment keywords
        suppl_keywords = ['suppl', 'spe', 'supp', 's']
        for keyword in suppl_keywords:
            if keyword in remaining:
                suppl = keyword
                remaining = remaining.replace(keyword, '').strip()

        # Extract any additional supplment number
        if remaining:
            suppl += ' ' + remaining

        # If suppl is still None, check if the number itself is a supplment keyword
        if suppl is None and number in suppl_keywords:
            suppl = number
            number = None

        return number, suppl
    except Exception as e:
        print(f"An error occurred: {e}")
        return None, None

