def _fromutc(self, dt):
    if not dt.tzinfo:
        raise ValueError("The provided datetime must be timezone-aware.")

    try:
        # Convert the datetime to UTC
        dt_utc = dt.astimezone(datetime.timezone.utc)
    except Exception as e:
        raise ValueError(f"Error converting datetime to UTC: {e}")

    # Calculate the offset difference
    offset_diff = self.utcoffset(dt) - self.utcoffset(dt_utc)

    # Adjust the datetime by the offset difference
    adjusted_dt = dt + offset_diff

    # Check if the adjusted datetime is in a fold state
    fold = adjusted_dt.replace(fold=1).dst() != adjusted_dt.replace(fold=0).dst()

    return adjusted_dt.replace(fold=fold)

