    fold = naive in (self.fromutc(dt_utc - timedelta(hours=1)).replace(tzinfo=None),
                     self.fromutc(dt_utc + timedelta(hours=1)).replace(tzinfo=None))

    if fold:
        # Determine if the datetime is the first occurrence or the second occurrence
        first_occurrence = dt_target.utcoffset() < dt_target.fold + 1
        if not first_occurrence:
            dt_target = dt_target.replace(fold=1)

    return dt_target

