    if not isinstance(args, (list, tuple)):
        raise TypeError("Arguments must be a list or tuple")

    if not all(isinstance(arg, str) for arg in args):
        raise ValueError("Each argument must be a string")

    if cwd is not None and not os.path.isdir(cwd):
        raise ValueError(f"Provided cwd '{cwd}' is not a valid directory")

    full_command = commands + args
    try:
        result = subprocess.run(
            full_command,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            check=True,
            stderr=subprocess.STDOUT if hide_stderr else subprocess.PIPE
        )
        if verbose:
            print(f"Command output: {result.stdout}")
        return result.stdout
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with error: {e.stderr}")
        return e.stderr
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

