def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    import argparse
    import borgmatic.commands.arguments

    def argument_to_completion(argument):
        if argument.name().startswith('--'):
            return argument.name().lstrip('-')
        if argument.nargs == '+':
            return f"{argument.name()}*"
        if argument.nargs == '?':
            return f"{argument.name()}?"
        return argument.name()

    parser = borgmatic.commands.arguments.make_parsers()
    completion_script_lines = ["_borgmatic() {", "    local cur prev opts", "    COMPREPLY=()"]
    completion_script_lines.append(f"    cur=\"${{COMP_WORDS[COMP_CWORD]}\"")
    completion_script_lines.append(f"    prev=\"${{COMP_WORDS[COMP_CWORD-1]}\"")
    completion_script_lines.append("    opts=\"")

    for subparser in parser._subparsers._actions:
        if isinstance(subparser, argparse._SubParsersAction):
            for choice, subcommand_parser in subparser.choices.items():
                completion_script_lines.append(choice)
                for action in subcommand_parser._actions:
                    if action.option_strings:
                        for option_string in action.option_strings:
                            completion_script_lines.append(option_string.lstrip('-'))
                    else:
                        completion_script_lines.append(argument_to_completion(action))

    completion_script_lines.append("\"")
    completion_script_lines.append('    if [[ ${cur} == -* ]] ; then')
    completion_script_lines.append('        COMPREPLY=( $(compgen -W "${opts}" -- ${cur}) )')
    completion_script_lines.append('        return 0')
    completion_script_lines.append('    fi')
    completion_script_lines.append('}')
    completion_script_lines.append('complete -F _borgmatic borgmatic')
    return "\n".join(completion_script_lines)

def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        import borgmatic.commands.arguments
        import argparse
        import os

        # Create a parser for bash completion
        parser = borgmatic.commands.arguments.parse_arguments()

        # Function to recursively extract options
        def extract_options(parser, prefix=''):
            options = []
            for action in parser._actions:
                if isinstance(action, argparse._SubParsersAction):
                    for choice, sub_parser in action.choices.items():
                        options.extend(extract_options(sub_parser, f'{prefix} {choice}'))
                else:
                    for option_string in action.option_strings:
                        if option_string.startswith('--'):
                            options.append(f'{prefix} {option_string}')
            return options

        # Extract all options
        all_options = extract_options(parser)

        # Generate bash completion script
        script = f"_borgmatic_completion() {{
            COMPREPLY=()
            local cur prev opts
            COMPREPLY=()
            cur=\"${{COMP_WORDS[COMP_CWORD]}}\"
            prev=\"${{COMP_WORDS[COMP_CWORD-1]}}\"
            opts=\"{' '.join(all_options)}\"
            COMPREPLY=( $(compgen -W \"${{opts}}\" -- ${{cur}}) )
            return 0
        }}
        complete -F _borgmatic_completion borgmatic
        "

        return script

    except Exception as e:
        return f"# Error generating bash completion script: {str(e)}"

