    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    try:
        if size[-1].isdigit():
            return int(size)
        else:
            multiplier = size[-1].upper()
            value = int(size[:-1])
            if multiplier == 'K':
                return value * 1000
            elif multiplier == 'M':
                return value * 1000**2
            elif multiplier == 'G':
                return value * 1000**3
            elif multiplier == 'T':
                return value * 1000**4
            else:
                raise ValueError(f"Invalid multiplier: {multiplier}")
    except (ValueError, IndexError) as e:
        raise ValueError(f"Invalid size format: {size} - {e}")

