def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    unit_mapping = {
        "second": "seconds",
        "minute": "minutes",
        "hour": "hours",
        "day": "days",
        "week": "weeks"
    }

    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError(f"Invalid frequency format: {frequency}")

    try:
        number = int(parts[0])
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {parts[0]}")

    unit = parts[1].lower().rstrip('s')  # Remove trailing 's' for plural units
    if unit not in unit_mapping:
        raise ValueError(f"Invalid unit in frequency: {parts[1]}")

    timedelta_kwargs = {unit_mapping[unit]: number}
    return datetime.timedelta(**timedelta_kwargs)

