def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    if not isinstance(image_href, str) or not image_href:
        raise ValueError("image_href must be a non-empty string")

    try:
        parsed_url = urllib.parse.urlparse(image_href)
    except Exception as e:
        raise ValueError(f"Invalid URL: {e}")

    image_id = parsed_url.path.strip('/').split('/')[-1]
    netloc = parsed_url.netloc
    use_ssl = parsed_url.scheme == 'https'

    return image_id, netloc, use_ssl

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    if not isinstance(image_href, str):
        raise ValueError("image_href must be a string")

    try:
        url = urllib.parse.urlparse(image_href)
    except Exception as e:
        raise ValueError(f"Invalid URL: {e}")

    if url.scheme not in ['http', 'https']:
        raise ValueError("URL must use http or https scheme")

    image_id = url.path.strip().split('/')[-1]
    netloc = url.netloc
    use_ssl = url.scheme == 'https'

    return (image_id, netloc, use_ssl)

