def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    try:
        # Collect all nodes that have no parent with respect to the given property
        for node in graph.subjects():
            if node not in graph.objects(predicate=prop):
                roots.add(node)
    except Exception as e:
        print(f"An error occurred: {e}")
    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    try:
        # Find all nodes that are not the object of any triple with the given property
        for node in graph.all_nodes():
            if not list(graph.subjects(predicate=prop, object=node)):
                roots.add(node)
    except Exception as e:
        print(f"An error occurred: {e}")

    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    try:
        for s, p, o in graph:
            if p == prop:
                if o not in graph.subjects(prop, None):
                    roots.add(o)
        return roots
    except Exception as e:
