def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    for subject, predicate, _ in graph:
        if predicate == prop and subject not in roots:
            is_root = True
            for _, _, parent in graph:
                if parent == subject:
                    is_root = False
                    break
            if is_root:
                roots.add(subject)

    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    try:
        nodes = set(graph.subjects(prop))
        while nodes:
            new_nodes = set()
            for node in nodes:
                if not any(graph.value(subj, prop, node) for subj in graph.subjects()):
                    roots.add(node)
                else:
                    new_nodes.add(node)
            nodes = new_nodes
    except Exception as e:
        print(f"An error occurred: {e}")
    return roots

