def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import os
    import json
    import logging

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as file:
                config = json.load(file)

            # Apply overrides
            config.update(overrides)

            # Resolve environment variables if required
            if resolve_env:
                for key, value in config.items():
                    if isinstance(value, str) and value.startswith('$'):
                        env_var_name = value[1:]
                        env_var_value = os.getenv(env_var_name)
                        if env_var_value is None:
                            log_records.append(logging.LogRecord(name='ConfigLoader', level=logging.ERROR, pathname=config_filename, lineno=0, msg=f'Environment variable {env_var_name} not found for key {key}', args=(), exc_info=None))
                        else:
                            config[key] = env_var_value

            config_dict[config_filename] = config

        except FileNotFoundError:
            log_records.append(logging.LogRecord(name='ConfigLoader', level=logging.ERROR, pathname=config_filename, lineno=0, msg=f'File not found: {config_filename}', args=(), exc_info=True))
        except json.JSONDecodeError as e:
            log_records.append(logging.LogRecord(name='ConfigLoader', level=logging.ERROR, pathname=config_filename, lineno=e.lineno, msg=f'JSON decode error: {e.msg}', args=(), exc_info=True))
        except Exception as e:
            log_records.append(logging.LogRecord(name='ConfigLoader', level=logging.ERROR, pathname=config_filename, lineno=0, msg=f'Unexpected error: {str(e)}', args=(), exc_info=True))

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
