def _resolve_env_vars(d):
    if isinstance(d, dict):
        for key, value in d.items():
            d[key] = _resolve_env_vars(value)
    elif isinstance(d, list):
        d = [_resolve_env_vars(item) for item in d]
    elif isinstance(d, str):
        d = os.path.expandvars(d)
    return d

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import configparser
    import os

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        if not isinstance(filename, str) or not os.path.isfile(filename):
            log_records.append(logging.makeLogRecord({
                'levelno': logging.ERROR,
                'levelname': 'ERROR',
                'msg': f"Invalid configuration filename: {filename}"
            }))
            continue

        config = configparser.ConfigParser()
        try:
            config.read(filename)
            config_dict[filename] = config

            if resolve_env:
                for section in config.sections():
                    for key, value in config.items(section):
                        config.set(section, key, os.path.expandvars(value))

            # Apply overrides
            if filename in overrides:
                for section, options in overrides[filename].items():
                    if not config.has_section(section):
                        config.add_section(section)
                    for key, value in options.items():
                        config.set(section, key, value)
                        config_dict[filename] = config

        except Exception as e:
            log_records.append(logging.makeLogRecord({
                'levelno': logging.ERROR,
                'levelname': 'ERROR',
                'msg': f"Failed to parse configuration file {filename}: {str(e)}"
            }))

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
