            log_records.append(logging.makeLogRecord({
                'levelno': logging.ERROR,
                'levelname': 'ERROR',
                'msg': f"Invalid configuration filename: {filename}"
            }))
            continue

        config = configparser.ConfigParser()
        try:
            with open(filename, 'r') as file:
                config.read_file(file)
        except FileNotFoundError:
            log_records.append(logging.makeLogRecord({
                'levelno': logging.ERROR,
                'levelname': 'ERROR',
                'msg': f"Configuration file not found: {filename}"
            }))
            continue
        except Exception as e:
            log_records.append(logging.makeLogRecord({
                'levelno': logging.ERROR,
                'levelname': 'ERROR',
                'msg': f"Error reading configuration file {filename}: {e}"
            }))
            continue

        if resolve_env:
            for section in config.sections():
                for key, value in config.items(section):
                    resolved_value = os.path.expandvars(value)
                    config.set(section, key, resolved_value)

        configurations[filename] = {section: dict(config.items(section)) for section in config.sections()}

        # Apply overrides
        for section, settings in overrides.items():
            if section in configurations[filename]:
                configurations[filename][section].update(settings)
            else:
                configurations[filename][section] = settings

    return configurations, log_records

def from_ticks(cls, ticks, tz=None):
    if not isinstance(ticks, int):
        raise ValueError("ticks must be an integer")
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")
    seconds = ticks // 1000000000
    nanoseconds = ticks % 1000000000
    time_obj = datetime.time(second=seconds % 60, minute=(seconds // 60) % 60, hour=seconds // 3600, microsecond=nanoseconds // 1000)
    return cls(time_obj.hour, time_obj.minute, time_obj.second, time_obj.microsecond, tzinfo=tz)

