def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []
    if not tentative:
        from zope.interface import providedBy
        if iface not in providedBy(candidate):
            errors.append(f"Candidate {candidate} does not claim to provide the interface {iface}")

    required_methods = iface.names()
    for name in required_methods:
        if not hasattr(candidate, name) or not callable(getattr(candidate, name)):
            errors.append(f"Candidate {candidate} does not define the required method {name}")

        if vtype is not None:
            from zope.interface.interface import InterfaceMethod
            if name in iface:
                method = iface[name]
                if isinstance(method, InterfaceMethod):
                    from inspect import signature
                    try:
                        sig = signature(getattr(candidate, name))
                        if not method.signature.issubset(sig):
                            errors.append(f"Method {name} of candidate {candidate} has incorrect signature")
                    except Exception as e:
                        errors.append(f"Error checking signature of method {name} of candidate {candidate}: {str(e)}")

    required_attributes = iface.names(all=True) - iface.names()
    for name in required_attributes:
        if not hasattr(candidate, name) or callable(getattr(candidate, name)):
            errors.append(f"Candidate {candidate} does not define the required attribute {name}")

    if errors:
        from zope.interface.exceptions import Invalid
        if len(errors) == 1:
            raise Invalid(f"Verification error: {errors[0]}")
        else:
            raise Invalid("Verification errors:\n" + "\n".join(f"- {error}" for error in errors))
    return True

