def _verify(iface, candidate, tentative=False, vtype=None):
    from zope.interface.exceptions import Invalid
    import inspect
    import itertools

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not claim to provide interface {iface}")

    required_methods = set(iface.names(type='method'))
    required_attributes = set(iface.names(type='attribute')) - required_methods

    actual_methods = {name for name, value in inspect.getmembers(candidate, predicate=inspect.ismethod)}
    actual_attributes = set(candidate.__dict__.keys()) | {name for name, value in inspect.getmembers(candidate, predicate=inspect.isdatadescriptor) if not callable(value)}

    missing_methods = required_methods - actual_methods
    for method in missing_methods:
        errors.append(f"Missing method: {method}")

