    for attribute in missing_attributes:
        errors.append(f"Missing attribute: {attribute}")

    for method_name in required_methods.intersection(actual_methods):
        try:
            required_signature = inspect.signature(iface[method_name])
            actual_signature = inspect.signature(candidate.__dict__[method_name])
        except ValueError:
            errors.append(f"Unable to inspect signature for method: {method_name}")
