        # Convert dictionary to Ansible compatible extra-vars format
        extra_vars = ' '.join(f'{key}={value}' for key, value in vars_dict.items())

        # Construct the full command
        command = ['ansible-playbook'] + cli_args + ['-e', extra_vars]

        # Execute the Ansible command
        process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()

        # Check for errors
        if process.returncode != 0:
            raise RuntimeError(f"Ansible playbook failed with error: {stderr.decode()}")

        # Return the stdout as Ansible results
        return stdout.decode()

    except Exception as e:
        return f"An error occurred: {str(e)}"

